files.guard.py:
"""The pre-dispatch guard. `allow` decides whether a proposed tool call runs.

Current behaviour: refuse the call if its text contains a known-bad substring.
"""

DENY_SUBSTRINGS = ["rm -rf", "sudo", "curl", ".env", ".ssh", "/etc"]


class Call:
    """One proposed tool call, as the harness hands it to the guard.

    `effect` is the tool schema's declaration of what the call does, as
    {"op": ..., "resource": ..., "persistence": ...}. `arg_sources` maps each
    argument name to where its value came from: "request" for the authenticated
    user request, "tool_output" for anything a tool returned, "literal" for a
    constant in the schema.
    """

    def __init__(self, tool, command=None, effect=None, arg_sources=None):
        self.tool = tool
        self.command = command
        self.effect = effect or {}
        self.arg_sources = arg_sources or {}


class Authority:
    """What the authenticated request permits. Compiled before the model runs."""

    def __init__(self, exec_prefixes=(), write_prefixes=(), budget=1):
        self.exec_prefixes = tuple(exec_prefixes)
        self.write_prefixes = tuple(write_prefixes)
        self.budget = budget


def allow(call, authority):
    text = call.command or ""
    for bad in DENY_SUBSTRINGS:
        if bad in text:
            return False
    return True

files.authz.py:
"""Delegation authorisation. Current design: an allowlist of tool names.

A sub-agent is handed a Grant. `authorize` decides whether it may make a call,
and `delegate` produces the Grant a sub-agent receives from its parent.
"""


class Call:
    """`arg_sources` maps each argument name to the origin of its value:
    "request" (the authenticated user request), "tool:<name>" (that tool's
    output), or "literal"."""

    def __init__(self, tool, args=None, arg_sources=None):
        self.tool = tool
        self.args = args or {}
        self.arg_sources = arg_sources or {}


class Grant:
    """`tools` is the set of permitted tool names. `bindings` maps a tool name
    to the argument origins that tool's arguments are permitted to have."""

    def __init__(self, tools=(), bindings=None):
        self.tools = set(tools)
        self.bindings = dict(bindings or {})


def authorize(call, grant):
    return call.tool in grant.tools


def delegate(parent, tools=(), bindings=None):
    """The Grant a sub-agent receives. Current design: whatever is asked for."""
    return Grant(tools=tools, bindings=bindings)
